'use client';

import * as React from 'react';

import type { ForecastType, LocationInput, MoonForecast as MoonData } from '@/lib/wxcn/types.js';
import { sampleMoon } from '@/lib/wxcn/moon.js';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { cn } from '@/lib/utils';
import MoonDisc from './moon-disc';

export type MoonForecastProps = {
	timeZone?: string;
	type?: ForecastType;
	size?: 'sm' | 'default' | 'lg';
	density?: 'compact' | 'comfortable';
	className?: string;
	location?: LocationInput;
	forecast?: MoonData;
	sourceLabel?: string;
};

const defaultLocation: LocationInput = {
	label: 'Austin, TX',
	latitude: 30.2672,
	longitude: -97.7431
};

export function MoonForecast({
	timeZone,
	type = 'summary',
	size = 'default',
	density = 'comfortable',
	className,
	location = defaultLocation,
	forecast = sampleMoon,
	sourceLabel = ''
}: MoonForecastProps) {
	const [visitorTimeZone, setVisitorTimeZone] = React.useState('UTC');
	React.useEffect(() => setVisitorTimeZone(Intl.DateTimeFormat().resolvedOptions().timeZone), []);
	const displayTimeZone = timeZone ?? visitorTimeZone;
	const date = React.useCallback(
		(value: string) =>
			new Intl.DateTimeFormat('en-US', {
				month: 'short',
				day: 'numeric',
				timeZone: displayTimeZone
			}).format(new Date(value)),
		[displayTimeZone]
	);
	const phase = forecast.age / 29.530588853;

	return (
		<Card
			style={{ containerType: 'inline-size' }}
			data-density={density}
			data-card-size={size}
			className={cn('min-w-0 overflow-hidden', className)}
		>
			<CardHeader>
				<CardTitle>Moon phase</CardTitle>
				<CardDescription>{location.label}</CardDescription>
			</CardHeader>
			<CardContent className={cn('grid', density === 'compact' ? 'gap-3' : 'gap-5')}>
				<div
					className={cn(
						'flex items-center gap-4',
						size === 'lg' && 'flex-col rounded-lg bg-muted/20 p-5 text-center'
					)}
				>
					<MoonDisc
						phase={phase}
						label={`${forecast.phaseName}, ${forecast.illumination}% illuminated`}
						className={
							size === 'sm'
								? 'size-16 shrink-0'
								: size === 'lg'
									? 'size-36 shrink-0'
									: 'size-24 max-w-[28cqw] shrink-0'
						}
					/>
					<div>
						<p
							style={{ fontSize: 'clamp(1rem,6cqw,1.5rem)' }}
							className={cn('font-medium tracking-tight', size === 'sm' ? 'text-lg' : 'text-2xl')}
						>
							{forecast.phaseName}
						</p>
						<p className="mt-2 text-sm text-muted-foreground">
							{forecast.illumination}% illuminated
						</p>
					</div>
				</div>
				{type !== 'simple' && (
					<dl className="moon-data divide-y text-sm">
						<div className="flex justify-between gap-4 pb-3">
							<dt className="text-muted-foreground">Moon age</dt>
							<dd>{forecast.age} days</dd>
						</div>
						<div className="flex justify-between gap-4 py-3">
							<dt className="text-muted-foreground">Next full moon</dt>
							<dd>{date(forecast.nextFullMoon)}</dd>
						</div>
						<div className="flex justify-between gap-4 pt-3">
							<dt className="text-muted-foreground">Next new moon</dt>
							<dd>{date(forecast.nextNewMoon)}</dd>
						</div>
					</dl>
				)}
				{sourceLabel && (
					<p className="text-[10px] text-muted-foreground">
						{sourceLabel} · {date(forecast.date)}
					</p>
				)}
			</CardContent>
		</Card>
	);
}

export default MoonForecast;

import * as React from 'react';

import { cn } from '@/lib/utils';

export type MoonDiscProps = React.SVGProps<SVGSVGElement> & {
	phase?: number;
	label?: string;
};

export function MoonDisc({ phase = 0.5, label = 'Full moon', className, ...props }: MoonDiscProps) {
	const id = React.useId().replace(/:/g, '');
	const p = ((phase % 1) + 1) % 1;
	const waxing = p <= 0.5;
	const sign = waxing ? 1 : -1;
	const terminator = Math.cos(p * Math.PI * 2) * sign;
	const points = Array.from({ length: 97 }, (_, i) => {
		const y = 1 - i / 48;
		return `${50 + 46 * Math.sqrt(Math.max(0, 1 - y * y)) * terminator} ${50 + 46 * y}`;
	});
	const light = `M50 4 A46 46 0 0 ${waxing ? 1 : 0} 50 96 L${points.join(' L')} Z`;

	return (
		<svg viewBox="0 0 100 100" className={cn(className)} role="img" aria-label={label} {...props}>
			<defs>
				<radialGradient id={`${id}-surface`} cx="42%" cy="38%" r="65%">
					<stop stopColor="#f1f1ed" />
					<stop offset=".72" stopColor="#d9dad5" />
					<stop offset="1" stopColor="#a8aca8" />
				</radialGradient>
			</defs>
			<circle cx="50" cy="50" r="46" fill="#30343a" />
			<path d={light} fill={`url(#${id}-surface)`} />
			<circle
				cx="50"
				cy="50"
				r="46"
				fill="none"
				stroke="currentColor"
				strokeOpacity=".08"
				strokeWidth=".5"
			/>
		</svg>
	);
}

export default MoonDisc;

export type CardSize = 'sm' | 'default' | 'lg';
export type CardDensity = 'compact' | 'comfortable';
export type ForecastType = 'summary' | 'detailed' | 'simple';
export type IconSet = 'hugeicons' | 'phosphor-svelte' | 'lucide' | 'tabler' | 'remix';
export type WeatherUnit = 'fahrenheit' | 'celsius';
export type TideUnit = 'ft' | 'meter';

export type LocationInput = {
	label?: string;
	latitude: number;
	longitude: number;
	station?: string;
	timeZone?: string;
};

export type WeatherPeriod = {
	name: string;
	startTime: string;
	endTime?: string;
	temperature: number;
	temperatureUnit: string;
	windSpeed: string;
	windDirection: string;
	shortForecast: string;
	detailedForecast: string;
	isDaytime: boolean;
};

export type TidePrediction = {
	time: string;
	height: string;
	type: 'H' | 'L';
};

export type MoonForecast = {
	date: string;
	phaseName: string;
	illumination: number;
	age: number;
	nextFullMoon: string;
	nextNewMoon: string;
};

/** Feet above MLLW. Prefer ISO 8601 timestamps with an explicit offset. */
export type TidePoint = { time: string; height: string };
export type TideReading = TidePoint;

/** Current observed conditions; daily extrema use temperatureUnit and the location's calendar day. */
export type CurrentWeather = WeatherPeriod & {
	observedAt: string;
	highToday?: number;
	lowToday?: number;
};

import type { MoonForecast } from './types.js';

const synodicMonth = 29.530588853;
const knownNewMoon = Date.UTC(2000, 0, 6, 18, 14);
const dayMs = 86_400_000;

function phaseName(age: number) {
	if (age < 1.84566) return 'New Moon';
	if (age < 5.53699) return 'Waxing Crescent';
	if (age < 9.22831) return 'First Quarter';
	if (age < 12.91963) return 'Waxing Gibbous';
	if (age < 16.61096) return 'Full Moon';
	if (age < 20.30228) return 'Waning Gibbous';
	if (age < 23.99361) return 'Last Quarter';
	if (age < 27.68493) return 'Waning Crescent';
	return 'New Moon';
}

function addDays(date: Date, days: number) {
	const next = new Date(date);
	next.setUTCDate(next.getUTCDate() + days);
	return next;
}

export function getMoonForecast(date = new Date()): MoonForecast {
	const daysSince = (date.getTime() - knownNewMoon) / dayMs;
	const cycles = daysSince / synodicMonth;
	const age = (cycles - Math.floor(cycles)) * synodicMonth;
	const angle = (age / synodicMonth) * Math.PI * 2;
	const illumination = Math.round(((1 - Math.cos(angle)) / 2) * 100);
	const daysToNew = synodicMonth - age;
	const daysToFull = age < synodicMonth / 2 ? synodicMonth / 2 - age : synodicMonth * 1.5 - age;

	return {
		date: date.toISOString(),
		phaseName: phaseName(age),
		illumination,
		age: Number(age.toFixed(1)),
		nextFullMoon: addDays(date, Math.ceil(daysToFull)).toISOString(),
		nextNewMoon: addDays(date, Math.ceil(daysToNew)).toISOString()
	};
}

export const sampleMoon = getMoonForecast(new Date('2026-09-06T12:00:00-05:00'));
